UPDATE "Equipo"
SET "contenido" = '<h2>Cirugía coordinada para cada institución</h2><p>Conformamos equipos quirúrgicos según la complejidad del procedimiento y los requerimientos de la institución.</p><h2>Alcance del equipo</h2><ul><li>Cirugía abierta y laparoscópica</li><li>Procedimientos programados y de urgencia</li><li>Coordinación médica y administrativa</li></ul><h2>Modalidad de trabajo</h2><p>Kadima articula disponibilidad, documentación y condiciones operativas con la institución solicitante.</p>'
WHERE "nombre" = 'Cirugía General' AND "contenido" = "descripcion";

UPDATE "Equipo"
SET "contenido" = '<h2>Atención cardiovascular especializada</h2><p>Profesionales preparados para acompañar estudios diagnósticos, seguimiento clínico e intervenciones cardiovasculares.</p><h2>Prestaciones</h2><ul><li>Evaluación y seguimiento cardiológico</li><li>Estudios diagnósticos</li><li>Articulación con servicios de mayor complejidad</li></ul><h2>Coordinación institucional</h2><p>Organizamos el equipo de acuerdo con la necesidad asistencial y la capacidad operativa de cada institución.</p>'
WHERE "nombre" = 'Cardiología' AND "contenido" = "descripcion";

UPDATE "Equipo"
SET "contenido" = '<h2>Respuesta integral en traumatología</h2><p>Equipos de ortopedia y traumatología para diagnóstico, tratamiento y resolución quirúrgica de patologías del aparato locomotor.</p><h2>Áreas de cobertura</h2><ul><li>Evaluación traumatológica</li><li>Cirugía ortopédica</li><li>Seguimiento postoperatorio</li></ul><h2>Trabajo con instituciones</h2><p>Coordinamos perfiles profesionales, disponibilidad y documentación según cada solicitud.</p>'
WHERE "nombre" = 'Traumatología' AND "contenido" = "descripcion";

UPDATE "Equipo"
SET "contenido" = '<h2>Especialistas en sistema nervioso</h2><p>Profesionales de neurología clínica y neurocirugía para patologías de distinta complejidad.</p><h2>Abordaje</h2><ul><li>Evaluación neurológica</li><li>Seguimiento clínico</li><li>Derivación y coordinación neuroquirúrgica</li></ul><h2>Disponibilidad</h2><p>La conformación del equipo se adapta al tipo de prestación y a las condiciones de la institución.</p>'
WHERE "nombre" = 'Neurología' AND "contenido" = "descripcion";

UPDATE "Equipo"
SET "contenido" = '<h2>Atención oftalmológica integral</h2><p>Equipos especializados para diagnóstico, seguimiento y tratamiento médico o quirúrgico de patologías oculares.</p><h2>Servicios</h2><ul><li>Evaluación oftalmológica</li><li>Cirugía ocular</li><li>Seguimiento de pacientes</li></ul><h2>Coordinación</h2><p>Kadima facilita la vinculación entre profesionales e instituciones para cada requerimiento.</p>'
WHERE "nombre" = 'Oftalmología' AND "contenido" = "descripcion";

UPDATE "Equipo"
SET "contenido" = '<h2>Cuidado neonatal especializado</h2><p>Profesionales capacitados para la atención de recién nacidos en áreas de cuidados intensivos y no intensivos.</p><h2>Cobertura</h2><ul><li>Atención neonatal</li><li>Cuidados intensivos</li><li>Acompañamiento en instituciones materno-infantiles</li></ul><h2>Organización del servicio</h2><p>Definimos la dotación profesional según la complejidad y las necesidades operativas.</p>'
WHERE "nombre" = 'Neonatología' AND "contenido" = "descripcion";

UPDATE "Equipo"
SET "contenido" = '<h2>Especialistas en salud respiratoria</h2><p>Equipos para el diagnóstico y tratamiento de enfermedades pulmonares agudas y crónicas.</p><h2>Áreas de intervención</h2><ul><li>Evaluación neumonológica</li><li>Seguimiento de patologías respiratorias</li><li>Coordinación con servicios complementarios</li></ul><h2>Trabajo institucional</h2><p>La cobertura se organiza según el perfil de pacientes y la complejidad requerida.</p>'
WHERE "nombre" = 'Neumonología' AND "contenido" = "descripcion";

UPDATE "Equipo"
SET "contenido" = '<h2>Acompañamiento oncológico integral</h2><p>Profesionales para las distintas etapas del diagnóstico, tratamiento y seguimiento de pacientes oncológicos.</p><h2>Alcance</h2><ul><li>Evaluación clínica</li><li>Planificación y seguimiento del tratamiento</li><li>Articulación interdisciplinaria</li></ul><h2>Coordinación con la institución</h2><p>Kadima organiza el equipo de acuerdo con el circuito asistencial definido.</p>'
WHERE "nombre" = 'Oncología' AND "contenido" = "descripcion";

UPDATE "Equipo"
SET "contenido" = '<h2>¿Buscás otra especialidad?</h2><p>Analizamos requerimientos que no figuran en el listado y evaluamos la conformación del equipo adecuado.</p><h2>Cómo solicitarla</h2><ul><li>Indicá la especialidad requerida</li><li>Detallá la institución y el tipo de cobertura</li><li>Informá fechas y nivel de complejidad</li></ul><h2>Evaluación</h2><p>Nuestro equipo confirma disponibilidad y condiciones de trabajo antes de avanzar.</p>'
WHERE "nombre" = 'Otras especialidades' AND "contenido" = "descripcion";
